def totals_by_category(csv_text):
    """Sum integer amounts per category from CSV text with header category,amount."""
    if csv_text is None:
        return {}

    totals = {}
    header_seen = False

    for raw_line in csv_text.splitlines():
        line = raw_line.strip()
        if not line:
            continue

        parts = [p.strip() for p in line.split(",")]
        if not header_seen:
            header_seen = True
            if len(parts) >= 2 and parts[0].lower() == "category" and parts[1].lower() == "amount":
                continue

        if len(parts) < 2:
            continue

        category = parts[0]
        amount_text = parts[1]
        if not category:
            continue

        try:
            amount = int(amount_text)
        except (TypeError, ValueError):
            try:
                amount = int(float(amount_text))
            except (TypeError, ValueError):
                continue

        totals[category] = totals.get(category, 0) + amount

    return totals

